import { afterAll, expect, test } from 'vitest';
import React from 'react';
import { act } from 'react';
import ReactDOM from 'react-dom/client';
import { ThemeProvider } from '@gravity-ui/uikit';
import { App } from './App';

(globalThis as any).IS_REACT_ACT_ENVIRONMENT = true;

const sleep = (ms: number) => new Promise((r) => setTimeout(r, ms));
let root: ReactDOM.Root | undefined;
afterAll(() => act(() => root?.unmount()));

test('page renders calendar and date picker, and selecting a day updates state', async () => {
  const container = document.createElement('div');
  document.body.appendChild(container);
  root = ReactDOM.createRoot(container);
  await act(async () => {
    root!.render(
      <ThemeProvider theme="light">
        <App />
      </ThemeProvider>,
    );
  });
  // let the ru locale load
  await act(async () => { await sleep(300); });

  const html = container.innerHTML;
  expect(container.textContent).toContain('Выбор даты');
  expect(container.textContent).toContain('Дата не выбрана');

  // date picker input
  const input = container.querySelector('#date-picker');
  expect(input, 'date picker input exists').toBeTruthy();

  // inline calendar grid
  const grid = container.querySelector('[role="grid"]');
  expect(grid, 'calendar grid exists').toBeTruthy();
  const headers = Array.from(container.querySelectorAll('[role="columnheader"]')).map((e) => e.textContent);
  console.log('weekday headers:', headers.join(' '));
  expect(headers.length).toBe(7);
  // Russian locale => Monday first, 'пн'
  expect(headers[0]?.toLowerCase()).toBe('пн');

  // month caption contains Russian month name and year
  const caption = container.querySelector('.g-calendar__mode-switcher, [class*="mode-switcher"]')?.textContent;
  console.log('caption:', caption);
  expect(caption).toMatch(/2026/);

  // click on the 15th of the visible month
  const cells = Array.from(container.querySelectorAll('[role="gridcell"]')) as HTMLElement[];
  expect(cells.length).toBeGreaterThanOrEqual(28);
  const target = cells.find((c) => c.textContent?.trim() === '15' && !c.getAttribute('aria-disabled') && !c.className.includes('other'));
  expect(target, 'cell for day 15 found').toBeTruthy();
  const clickable = (target!.querySelector('[role="button"], button, div[tabindex]') as HTMLElement) ?? target!;
  await act(async () => {
    clickable.dispatchEvent(new MouseEvent('click', { bubbles: true }));
    (clickable as any).click?.();
  });
  await act(async () => { await sleep(50); });

  console.log('status text:', Array.from(container.querySelectorAll('span, div')).map((e) => e.textContent).find((t) => t?.startsWith('Выбрана дата')));
  expect(container.textContent).toMatch(/Выбрана дата: 15 \S+ 2026 \(15\.\d\d\.2026\)/);
  // input reflects value
  console.log('input value:', (input as HTMLInputElement).value);
  expect((input as HTMLInputElement).value).toMatch(/^15\.\d\d\.2026$/);
  expect(target!.getAttribute('aria-selected')).toBe('true');
  expect(html.length).toBeGreaterThan(0);
});
EOF
